package com.tradepilot.backtest.entity;
import jakarta.persistence.*; import org.hibernate.annotations.ColumnTransformer; import java.math.*; import java.time.*;
@Entity @Table(name="backtest_trades") public class BacktestTrade {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="backtest_run_id",nullable=false) private Long backtestRunId; @Column(name="trade_date",nullable=false) private LocalDate tradeDate; @Column(name="session_date") private LocalDate sessionDate; @Column(length=10) private String instrument; @Column(name="continuous_symbol",length=20) private String continuousSymbol; @Column(nullable=false,length=8) private String direction; @Column(name="setup_time") private Instant setupTime; @Column(name="entry_time",nullable=false) private Instant entryTime; @Column(name="entry_price",nullable=false,precision=16,scale=6) private BigDecimal entryPrice; @Column(name="stop_price",nullable=false,precision=16,scale=6) private BigDecimal stopPrice; @Column(name="initial_risk_points",precision=16,scale=6) private BigDecimal initialRiskPoints; @Column(name="tp1_price",precision=16,scale=6) private BigDecimal tp1Price; @Column(name="runner_target_price",precision=16,scale=6) private BigDecimal runnerTargetPrice; @Column(name="final_exit_time") private Instant finalExitTime; @Column(name="final_exit_price",precision=16,scale=6) private BigDecimal finalExitPrice; @Column(name="model_a_r",precision=16,scale=6) private BigDecimal modelAR; @Column(name="model_b_r",precision=16,scale=6) private BigDecimal modelBR; @Column(name="model_a_weighted_r",precision=16,scale=6) private BigDecimal modelAWeightedR; @Column(name="model_b_weighted_r",precision=16,scale=6) private BigDecimal modelBWeightedR; @Column(name="weekday_risk_multiplier",precision=8,scale=4) private BigDecimal weekdayRiskMultiplier; @Column(name="ambiguous_intrabar",nullable=false) private boolean ambiguousIntrabar; @Column(name="instrument_id",nullable=false) private Long instrumentId; @Column(name="setup_metadata_json",nullable=false,columnDefinition="jsonb") @ColumnTransformer(read="setup_metadata_json::text",write="?::jsonb") private String setupMetadataJson; @Column(name="created_at",nullable=false) private Instant createdAt;
 public void fill(Long runId,LocalDate day,String inst,String continuous,String dir,Instant setup,Instant entry,BigDecimal entryPx,BigDecimal stop,BigDecimal tp1,BigDecimal runner,Instant finalExit,BigDecimal finalExitPx,BigDecimal a,BigDecimal b,BigDecimal wa,BigDecimal wb,BigDecimal multiplier,Long contract,String metadata){backtestRunId=runId;tradeDate=day;sessionDate=day;instrument=inst;continuousSymbol=continuous;direction=dir;setupTime=setup;entryTime=entry;entryPrice=entryPx;stopPrice=stop;initialRiskPoints=entryPx.subtract(stop).abs();tp1Price=tp1;runnerTargetPrice=runner;finalExitTime=finalExit;finalExitPrice=finalExitPx;modelAR=a;modelBR=b;modelAWeightedR=wa;modelBWeightedR=wb;weekdayRiskMultiplier=multiplier;instrumentId=contract;setupMetadataJson=metadata;createdAt=Instant.now();}
 public Long getId(){return id;} public Long getBacktestRunId(){return backtestRunId;} public LocalDate getTradeDate(){return tradeDate;} public String getInstrument(){return instrument;} public String getContinuousSymbol(){return continuousSymbol;} public Long getInstrumentId(){return instrumentId;} public String getDirection(){return direction;} public Instant getEntryTime(){return entryTime;} public BigDecimal getEntryPrice(){return entryPrice;} public BigDecimal getStopPrice(){return stopPrice;} public BigDecimal getTp1Price(){return tp1Price;} public BigDecimal getRunnerTargetPrice(){return runnerTargetPrice;} public Instant getFinalExitTime(){return finalExitTime;} public BigDecimal getFinalExitPrice(){return finalExitPrice;} public BigDecimal getModelAR(){return modelAR;} public BigDecimal getModelBR(){return modelBR;} public BigDecimal getModelAWeightedR(){return modelAWeightedR;} public BigDecimal getModelBWeightedR(){return modelBWeightedR;} public String getSetupMetadataJson(){return setupMetadataJson;}
}
